def acq_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def acq_has(value,name):
    for item in acq_subterms(value):
        if item[0]==name:
            return True
    return False

def acq_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def acq_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        if isinstance(node,dict):
            by_id[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node=by_id[node_id]
            for term in acq_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def acq_role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='source_recipient_role_of' and len(item)>2:
            tags.add(str(item[2]))
        elif name in ('employees_of','internal_personnel_of'):
            tags.add('employees')
        elif name=='independent_contractors_of':
            tags.add('contractors')
        elif name=='consultants_of':
            tags.add('consultants')
        elif name=='agents_of':
            tags.add('agents')
        elif name=='professional_advisors_of':
            tags.add('professional-advisers')
        elif name=='legal_advisors_of':
            tags.add('legal-advisers')
        elif name=='financial_advisors_of':
            tags.add('financial-advisers')
        elif name=='accountants_of':
            tags.add('accountants')
        elif name=='lenders_of':
            tags.add('lenders')
        elif name=='third_parties':
            tags.add('third-parties')
        elif name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def acq_disclosure(task,entries):
    definitions=[]
    definition_roots=[]
    absence=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        elif term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not acq_has(action[1],'confidential_information'):
            continue
        relevant.append(root)
        row=(root,acq_role_tags(action[2],definitions),action[2])
        if term[0]=='permission':
            permissions.append(row)
        else:
            prohibitions.append(row)
    wanted={'employees'} if task=='nda-5' else {'contractors','consultants','agents','professional-advisers','legal-advisers','financial-advisers','accountants','lenders','third-parties'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if acq_has(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(used)}
    for root,tags,recipient in prohibitions:
        if acq_has(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=acq_entries(premises)
    if task in ('nda-5','nda-7'):
        return acq_disclosure(task,entries)
    disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    absolute_prohibitions=[]
    no_disposal=[]
    no_retention=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0]=='retention_prohibition':
            retention_prohibitions.append(root)
        elif term[0]=='absolute_retention_prohibition':
            absolute_prohibitions.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
        elif term[0]=='complete_source_no_retention_effect':
            no_retention.append(root)
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (acq_has(action,'return_to') or acq_has(action,'destroy')):
                continue
            relevant.append(root)
            if acq_has(trigger,'agreement_termination') or acq_has(trigger,'service_termination') or acq_has(trigger,'relationship_termination') or acq_has(trigger,'relationship_nonformation_deadline') or acq_has(trigger,'purpose_completion'):
                endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(endpoint)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(retention_prohibitions)}
    if absolute_prohibitions and disposal:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(absolute_prohibitions+[root for term,root in disposal])}
    relevant=[]
    for term,root in disposal:
        if acq_has(term[2],'return_to') or acq_has(term[2],'destroy'):
            relevant.append(root)
    if relevant or no_retention or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_retention+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}

