def planner_answer_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        rows=value.get('answers')
        if isinstance(rows,list):
            return rows
        if isinstance(rows,dict):
            return list(rows.values())
        return list(value.values())
    return []

def planner_answered_ids(value):
    out=set()
    for row in planner_answer_rows(value):
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            out.add(row.get('id'))
    return out

def apply(inputs,premises):
    source_output=inputs.get('source_output',{})
    statements=[]
    if isinstance(source_output,dict):
        value=source_output.get('statements',[])
        if isinstance(value,list):
            statements=value
    if statements:
        return {'queries':[]}
    answered=planner_answered_ids(inputs.get('semantic_answers',[]))
    units=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            units.append(span.get('id'))
    queries=[]
    if units and 'empty_source_disclosure_scout_v4' not in answered:
        queries.append({'id':'empty_source_disclosure_scout_v4','operation':'operative_disclosure_clause_scout_v3','unit_ids':units})
    if units and 'empty_source_disposal_scout_v4' not in answered:
        queries.append({'id':'empty_source_disposal_scout_v4','operation':'disposal_obligation_scout','unit_ids':units})
    return {'queries':queries}

